//! Numerical parity for one native Qwen3-TTS talker decoder block.
//!
//! The committed fixture is generated by
//! `tools/parity/qwen3_tts_block_dump_reference.py`, which imports the
//! official `Qwen3TTSTalkerDecoderLayer` at the pinned upstream revision.
//! The Rust implementation is not imported by that dumper, so this is an
//! independent oracle rather than a mirror-vs-itself check.

use vokra_core::json::{self, JsonValue};
use vokra_models::qwen3_tts::{
    Qwen3TtsBoundBlockWeights, Qwen3TtsTalkerConfig, qwen3_tts_talker_block_forward,
};

const FIXTURE: &[u8] = include_bytes!("fixtures/qwen3_tts/talker_block.json");
const UPSTREAM_REVISION: &str = "022e286b98fbec7e1e916cb940cdf532cd9f488e";

fn required<'a>(value: &'a JsonValue, key: &str) -> &'a JsonValue {
    value
        .get(key)
        .unwrap_or_else(|| panic!("Qwen3-TTS block fixture missing `{key}`"))
}

fn usize_field(value: &JsonValue, key: &str) -> usize {
    required(value, key)
        .as_u64()
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or_else(|| panic!("Qwen3-TTS block fixture `{key}` is not a usize"))
}

fn f32_field(value: &JsonValue, key: &str) -> f32 {
    match required(value, key) {
        JsonValue::Int(value) => *value as f32,
        JsonValue::Float(value) => *value as f32,
        other => panic!("Qwen3-TTS block fixture `{key}` is not numeric: {other:?}"),
    }
}

fn f32_array(value: &JsonValue, key: &str) -> Vec<f32> {
    required(value, key)
        .as_array()
        .unwrap_or_else(|| panic!("Qwen3-TTS block fixture `{key}` is not an array"))
        .iter()
        .enumerate()
        .map(|(index, value)| match value {
            JsonValue::Int(value) => *value as f32,
            JsonValue::Float(value) => *value as f32,
            other => {
                panic!("Qwen3-TTS block fixture `{key}` element {index} is not numeric: {other:?}")
            }
        })
        .collect()
}

#[test]
fn native_talker_block_matches_official_pytorch_layer() {
    let root = json::parse(FIXTURE).expect("parse committed Qwen3-TTS block fixture");
    assert_eq!(
        required(&root, "upstream_revision").as_str(),
        Some(UPSTREAM_REVISION),
        "fixture must remain pinned to the reviewed official revision"
    );
    assert_eq!(
        required(&root, "oracle").as_str(),
        Some("Qwen3TTSTalkerDecoderLayer.forward")
    );

    let fixture_config = required(&root, "config");
    let config = Qwen3TtsTalkerConfig {
        hidden_dim: usize_field(fixture_config, "hidden_dim") as u32,
        n_layer: 1,
        n_head: usize_field(fixture_config, "n_head") as u32,
        n_head_kv: usize_field(fixture_config, "n_head_kv") as u32,
        head_dim: usize_field(fixture_config, "head_dim") as u32,
        ffn_dim: usize_field(fixture_config, "ffn_dim") as u32,
        vocab_size: 32,
        text_vocab_size: 32,
        max_position_embeddings: 128,
        rope_base: f32_field(fixture_config, "rope_base"),
        rms_norm_eps: f32_field(fixture_config, "rms_norm_eps"),
        position_id_per_seconds: 13,
        num_code_groups: 16,
        text_hidden_size: 24,
    };

    let fixture_weights = required(&root, "weights");
    let weights = Qwen3TtsBoundBlockWeights {
        input_layernorm: f32_array(fixture_weights, "input_layernorm"),
        q_proj: f32_array(fixture_weights, "q_proj"),
        q_norm: f32_array(fixture_weights, "q_norm"),
        k_proj: f32_array(fixture_weights, "k_proj"),
        k_norm: f32_array(fixture_weights, "k_norm"),
        v_proj: f32_array(fixture_weights, "v_proj"),
        o_proj: f32_array(fixture_weights, "o_proj"),
        post_attention_layernorm: f32_array(fixture_weights, "post_attention_layernorm"),
        gate_proj: f32_array(fixture_weights, "gate_proj"),
        up_proj: f32_array(fixture_weights, "up_proj"),
        down_proj: f32_array(fixture_weights, "down_proj"),
    };
    let positions: Vec<[u32; 3]> = required(&root, "positions")
        .as_array()
        .expect("positions array")
        .iter()
        .enumerate()
        .map(|(token, row)| {
            let row = row
                .as_array()
                .unwrap_or_else(|| panic!("positions[{token}] is not an array"));
            assert_eq!(row.len(), 3, "positions[{token}] must have three axes");
            std::array::from_fn(|axis| {
                row[axis]
                    .as_u64()
                    .and_then(|value| u32::try_from(value).ok())
                    .unwrap_or_else(|| panic!("positions[{token}][{axis}] is not a u32"))
            })
        })
        .collect();
    let hidden = f32_array(&root, "hidden");
    let expected = f32_array(&root, "output");

    let actual = qwen3_tts_talker_block_forward(&config, &weights, &hidden, &positions)
        .expect("native Qwen3-TTS talker block forward");
    assert_eq!(actual.len(), expected.len());

    let mut max_abs = 0.0f32;
    let mut sum_abs = 0.0f64;
    for (&actual, &expected) in actual.iter().zip(&expected) {
        let error = (actual - expected).abs();
        max_abs = max_abs.max(error);
        sum_abs += f64::from(error);
    }
    let mean_abs = sum_abs / actual.len() as f64;
    eprintln!("Qwen3-TTS official block parity: max_abs={max_abs:.9e}, mean_abs={mean_abs:.9e}");

    // Calibrated on the independent official fixture on x86_64 VAST:
    // max_abs=3.576278687e-7, mean_abs=9.322927023e-8.  These fixed bounds
    // retain narrow headroom for libm/platform ordering without masking a
    // changed RoPE, GQA, normalization, or residual formula.
    assert!(max_abs < 1.0e-6, "max_abs={max_abs:.9e}");
    assert!(mean_abs < 2.0e-7, "mean_abs={mean_abs:.9e}");
}
